class AppThemes {
  static final ValueNotifier<int> themeNotifier = ValueNotifier(0);

  static const List<Map<String, Color>> palettes = [
    { // Standard Light
      'purple1': Color(0xFF8E2DE2),
      'purple2': Color(0xFF4A00E0),
      'bg': Color(0xFFFFFDF7),
      'card': Color(0xFFFFFFFF),
      'text': Color(0xFF2D3748),
      'border': Color(0xFFE2E8F0),
      'muted': Color(0xFF718096),
    },
    { // Dark Night
      'purple1': Color(0xFF9F7AEA),
      'purple2': Color(0xFF805AD5),
      'bg': Color(0xFF1A202C),
      'card': Color(0xFF2D3748),
      'text': Color(0xFFF7FAFC),
      'border': Color(0xFF4A5568),
      'muted': Color(0xFFA0AEC0),
    },
    { // Golden Sepia
      'purple1': Color(0xFFDD6B20),
      'purple2': Color(0xFFC05621),
      'bg': Color(0xFFFFFBEB),
      'card': Color(0xFFFFFFFF),
      'text': Color(0xFF451A03),
      'border': Color(0xFFFCD34D),
      'muted': Color(0xFF92400E),
    },
    { // Royal Ocean
      'purple1': Color(0xFF2563EB),
      'purple2': Color(0xFF1D4ED8),
      'bg': Color(0xFFF0F9FF),
      'card': Color(0xFFFFFFFF),
      'text': Color(0xFF0F172A),
      'border': Color(0xFFBAE6FD),
      'muted': Color(0xFF475569),
    },
    { // Emerald Forest
      'purple1': Color(0xFF059669),
      'purple2': Color(0xFF047857),
      'bg': Color(0xFFF0FDF4),
      'card': Color(0xFFFFFFFF),
      'text': Color(0xFF064E3B),
      'border': Color(0xFFBBF7D0),
      'muted': Color(0xFF166534),
    },
    { // Tanjore Gold (Royal Dark)
      'purple1': Color(0xFFD4AF37), // Rich antique gold
      'purple2': Color(0xFFB8941F), // Deep temple gold
      'bg': Color(0xFF120008),      // Deep maroon-black
      'card': Color(0xFF1E0C12),    // Dark wine burgundy
      'text': Color(0xFFF5E6C8),    // Ivory cream
      'border': Color(0xFF6B4226),  // Warm copper border
      'muted': Color(0xFFAA9B6F),   // Muted gold
    }
  ];

  /// Whether the current theme is a dark theme
  static bool get isDark => themeNotifier.value == 1 || themeNotifier.value == 5;
  /// Whether the current theme is Tanjore Gold
  static bool get isTanjore => themeNotifier.value == 5;

  static void setTheme(int i) {
    if (i < 0 || i >= palettes.length) return;
    final p = palettes[i];
    kPurple1 = p['purple1']!;
    kPurple2 = p['purple2']!;
    kBg = p['bg']!;
    kCard = p['card']!;
    kText = p['text']!;
    kBorder = p['border']!;
    kMuted = p['muted']!;
    // Adapt accent colors for dark themes
    if (i == 5) { // Tanjore Gold
      kOrange = const Color(0xFFD4AF37); // Gold
      kTeal = const Color(0xFFCDA434);   // Warm gold
      kGreen = const Color(0xFFB8941F);  // Deep gold
    } else {
      kOrange = const Color(0xFFDD6B20);
      kTeal = const Color(0xFF319795);
      kGreen = const Color(0xFF047857);
    }
    themeNotifier.value = i;
    // Persist theme choice
    SharedPreferences.getInstance().then((prefs) => prefs.setInt('app_theme', i));
  }

  static Future<void> loadTheme() async {
    final prefs = await SharedPreferences.getInstance();
    final idx = prefs.getInt('app_theme') ?? 0;
    setTheme(idx);
  }
}

// ─────────────────────────────────────────────
// Kundali chart style (South / North Indian)
// ─────────────────────────────────────────────
class ChartStyle {
  static final ValueNotifier<String> styleNotifier = ValueNotifier('south');

  static String get current => styleNotifier.value;
  static bool get isNorth => styleNotifier.value == 'north';

  static void setStyle(String style) {
    if (style != 'south' && style != 'north') return;
    styleNotifier.value = style;
    SharedPreferences.getInstance().then((prefs) => prefs.setString('chart_style', style));
  }

  static Future<void> loadStyle() async {
    final prefs = await SharedPreferences.getInstance();
    final s = prefs.getString('chart_style') ?? 'south';
    styleNotifier.value = s;
  }
}

// ─────────────────────────────────────────────
// Varga Lagna Style: shastra (rashi lagna) vs modern (divisional lagna)
// Controls whether D9/D3 etc. use rashi lagna or divisional lagna as house 1
// ─────────────────────────────────────────────
class VargaLagnaStyle {
  static final ValueNotifier<bool> notifier = ValueNotifier(true); // true = modern (default)

  /// true = Modern style (Navamsha Lagna as house 1)
  /// false = Shastra style (Rashi Lagna as house 1)
  static bool get useVargaLagna => notifier.value;

  static void toggle(bool v) {
    notifier.value = v;
    SharedPreferences.getInstance().then((prefs) => prefs.setBool('varga_lagna_modern', v));
  }

  static Future<void> load() async {
    final prefs = await SharedPreferences.getInstance();
    notifier.value = prefs.getBool('varga_lagna_modern') ?? true;
  }
}
// ─────────────────────────────────────────────
// Samshaka mode: show navamsha number instead of degree
// ─────────────────────────────────────────────
class SamshakaMode {
  static final ValueNotifier<bool> notifier = ValueNotifier(false);

  static bool get isActive => notifier.value;

  static void toggle(bool v) {
    notifier.value = v;
    SharedPreferences.getInstance().then((prefs) => prefs.setBool('samshaka_mode', v));
  }

  static Future<void> load() async {
    final prefs = await SharedPreferences.getInstance();
    notifier.value = prefs.getBool('samshaka_mode') ?? false;
  }

  /// Get navamsha rashi number (1-12) for a given longitude
  static int navamshaSign(double longitude) {
    final rashi = (longitude / 30).floor() % 12;
    final block = rashi % 4; // 0=fire, 1=earth, 2=air, 3=water
    final start = [0, 9, 6, 3][block]; // Aries, Cap, Libra, Cancer
    final steps = ((longitude % 30) / 3.33333).floor();
    return ((start + steps) % 12) + 1; // 1-based
  }
}

// ─────────────────────────────────────────────
// Single letter mode: show only abbreviation, no degrees
// ─────────────────────────────────────────────
class SingleLetterMode {
  static final ValueNotifier<bool> notifier = ValueNotifier(false);

  static bool get isActive => notifier.value;

  static void toggle(bool v) {
    notifier.value = v;
    SharedPreferences.getInstance().then((prefs) => prefs.setBool('single_letter_mode', v));
  }

  static Future<void> load() async {
    final prefs = await SharedPreferences.getInstance();
    notifier.value = prefs.getBool('single_letter_mode') ?? false;
  }
}

// ─────────────────────────────────────────────
// App Language / Locale (5 languages)
// ─────────────────────────────────────────────
class AppLocale {
  static final ValueNotifier<String> langNotifier = ValueNotifier('kn');
  static String get current => langNotifier.value;
  static bool get isHindi => current == 'hi';

  static void setLang(String lang) {
    if (!['kn', 'hi', 'ta', 'te', 'ml'].contains(lang)) return;
    langNotifier.value = lang;
    SharedPreferences.getInstance().then((prefs) => prefs.setString('app_lang', lang));
  }

  static Future<void> loadLang() async {
    final prefs = await SharedPreferences.getInstance();
    langNotifier.value = prefs.getString('app_lang') ?? 'kn';
  }

  /// Get localized string by key — falls back to Kannada then key
  static String l(String key) {
    final langStrings = _allStrings[current];
    if (langStrings != null && langStrings.containsKey(key)) return langStrings[key]!;
    final knFallback = _allStrings['kn'];
    if (knFallback != null && knFallback.containsKey(key)) return knFallback[key]!;
    return key;
  }

  /// Get the Kannada value for a key (used by translateKn for reverse lookup)
  static String l_kn(String key) {
    final kn = _allStrings['kn'];
    if (kn != null && kn.containsKey(key)) return kn[key]!;
    return key;
  }

