// ─────────────────────────────────────────────
// Responsive helpers
// ─────────────────────────────────────────────
bool isTablet(BuildContext context) => MediaQuery.of(context).size.width >= 600;

/// Wraps content with a max-width constraint on tablets.
/// On mobile, renders child full-width. On tablets, centers
/// child with maxWidth (default 600px).
class ResponsiveCenter extends StatelessWidget {
  final Widget child;
  final double maxWidth;
  const ResponsiveCenter({super.key, required this.child, this.maxWidth = 600});

  @override
  Widget build(BuildContext context) {
    if (!isTablet(context)) return child;
    return Center(
      child: ConstrainedBox(
        constraints: BoxConstraints(maxWidth: maxWidth),
        child: child,
      ),
    );
  }
}


// ─────────────────────────────────────────────
// Header widget (gradient banner — gold for Tanjore)
// ─────────────────────────────────────────────
class AppHeader extends StatelessWidget {
  const AppHeader({super.key});

  @override
  Widget build(BuildContext context) {
    final isTanjore = AppThemes.isTanjore;
    return Container(
      margin: const EdgeInsets.fromLTRB(16, 16, 16, 8),
      padding: const EdgeInsets.all(20),
      decoration: BoxDecoration(
        gradient: LinearGradient(
          colors: isTanjore
              ? [const Color(0xFF2A1118), const Color(0xFF1E0C12)]
              : [kPurple1, kPurple2],
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
        ),
        borderRadius: BorderRadius.circular(16),
        boxShadow: [
          if (isTanjore)
            BoxShadow(
              color: const Color(0xFFD4AF37).withOpacity(0.25),
              blurRadius: 20,
              spreadRadius: 1,
              offset: const Offset(0, 2),
            )
          else
            BoxShadow(
              color: kPurple2.withOpacity(0.3),
              blurRadius: 15,
              offset: const Offset(0, 4),
            ),
        ],
        border: Border.all(
          color: isTanjore ? const Color(0xFFD4AF37) : const Color(0xFFF6D365),
          width: isTanjore ? 1.5 : 0,
        ),
      ),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          if (isTanjore) ...[
            Text('ॐ', style: TextStyle(fontSize: 28, color: const Color(0xFFD4AF37), fontWeight: FontWeight.bold)),
            const SizedBox(height: 4),
          ],
          Text(
            isTanjore ? "'ಭಾರತೀಯಮ್'" : 'ಭಾರತೀಯಮ್',
            style: TextStyle(
              color: isTanjore ? const Color(0xFFD4AF37) : Colors.white,
              fontSize: 24,
              fontWeight: FontWeight.w800,
              letterSpacing: 1.2,
              shadows: isTanjore ? [
                Shadow(color: const Color(0xFFD4AF37).withOpacity(0.5), blurRadius: 12),
              ] : null,
            ),
          ),
        ],
      ),
    );
  }
}

// ─────────────────────────────────────────────
// Card wrapper
// ─────────────────────────────────────────────
class AppCard extends StatelessWidget {
  final Widget child;
  final EdgeInsets? padding;
  const AppCard({super.key, required this.child, this.padding});

  @override
  Widget build(BuildContext context) {
    final isTanjore = AppThemes.isTanjore;
    return Container(
      margin: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
      padding: padding ?? const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: kCard,
        borderRadius: BorderRadius.circular(16),
        border: isTanjore
            ? Border.all(color: const Color(0xFFD4AF37).withOpacity(0.4), width: 1.2)
            : Border.all(color: kBorder),
        boxShadow: [
          if (isTanjore)
            BoxShadow(
              color: const Color(0xFFD4AF37).withOpacity(0.08),
              blurRadius: 12,
              offset: const Offset(0, 2),
            )
          else
            BoxShadow(
              color: Colors.black.withOpacity(0.03),
              blurRadius: 16,
              offset: const Offset(0, 4),
            ),
        ],
      ),
      child: child,
    );
  }
}

